ALTER TABLE public.push_devices ADD COLUMN active boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.claim_push_batch(_limit integer DEFAULT 20) RETURNS TABLE(queue_id uuid,device_id uuid,device_token text,auction_id uuid,title text,category_name text,image_path text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH candidates AS (SELECT q.id FROM public.push_outbox q JOIN public.push_devices d ON d.id=q.device_id AND d.active JOIN public.notification_preferences p ON p.user_id=q.user_id AND p.new_auctions JOIN public.auctions a ON a.id=q.auction_id AND a.status='active' WHERE q.status='pending' AND (cardinality(p.categories)=0 OR a.category_id=ANY(p.categories)) ORDER BY q.created_at LIMIT least(greatest(_limit,1),20) FOR UPDATE OF q SKIP LOCKED), claimed AS (UPDATE public.push_outbox q SET status='sending',claimed_at=now() FROM candidates c WHERE q.id=c.id RETURNING q.*) SELECT c.id,d.id,d.token,a.id,a.title,coalesce(cat.name,'Subasta'),CASE WHEN a.auction_type='item' THEN a.images[1] ELSE NULL END FROM claimed c JOIN public.push_devices d ON d.id=c.device_id JOIN public.auctions a ON a.id=c.auction_id LEFT JOIN public.categories cat ON cat.id=a.category_id $$;
CREATE OR REPLACE FUNCTION public.service_bid_details_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.auctions a JOIN public.service_requests r ON r.auction_id=a.id WHERE a.id=NEW.auction_id AND a.auction_type='service') THEN IF NOT public.service_details_allowed(NEW.auction_id) OR EXISTS(SELECT 1 FROM public.service_requests r WHERE r.auction_id=NEW.auction_id AND r.request->>'category'='transport' AND NOT r.locations_verified) THEN RAISE EXCEPTION 'Detalles privados o ubicaciones no disponibles para ofertar'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER service_bid_details_guard BEFORE INSERT ON public.bids FOR EACH ROW EXECUTE FUNCTION public.service_bid_details_guard();
REVOKE DELETE ON public.push_devices FROM authenticated;
COMMENT ON COLUMN public.push_devices.active IS 'Retire device without deleting immutable delivery history';